/// The error of a file function, in detail.
enum ZmidiClipError {
  /// No error.
  ZMIDI_CLIP_ERROR_NONE(0),

  /// The bytes do not start with the File Header.
  ZMIDI_CLIP_ERROR_BAD_HEADER(1),

  /// A trailing partial word, or a UMP cut by the end of the data.
  ZMIDI_CLIP_ERROR_TRUNCATED(2),

  /// A byte follows End of Clip.
  ZMIDI_CLIP_ERROR_DATA_AFTER_END(3),

  /// The buffer cannot hold the bytes.
  ZMIDI_CLIP_ERROR_BUFFER_TOO_SMALL(4),

  /// A bad clip configuration.
  ZMIDI_CLIP_ERROR_INVALID_CONFIG(5),

  /// The words are not one whole UMP.
  ZMIDI_CLIP_ERROR_INVALID_MESSAGE(6),

  /// A tick earlier than the last one.
  ZMIDI_CLIP_ERROR_OUT_OF_ORDER(7),

  /// A Property Exchange message.
  ZMIDI_CLIP_ERROR_PROPERTY_EXCHANGE(8),

  /// A message that the writer writes itself.
  ZMIDI_CLIP_ERROR_RESERVED_MESSAGE(9),

  /// Set Tempo off the 1/24 quarter note grid.
  ZMIDI_CLIP_ERROR_TEMPO_TIMING(10),

  /// Set Time Signature not at a bar boundary.
  ZMIDI_CLIP_ERROR_BAR_TIMING(11),

  /// A different tick inside one multi-UMP Lyrics or Ruby message.
  ZMIDI_CLIP_ERROR_FLEX_TIMING(12),

  /// The call is not allowed in the current phase.
  ZMIDI_CLIP_ERROR_WRONG_PHASE(13);

  final int value;
  const ZmidiClipError(this.value);

  static ZmidiClipError fromValue(int value) => switch (value) {
    0 => ZMIDI_CLIP_ERROR_NONE,
    1 => ZMIDI_CLIP_ERROR_BAD_HEADER,
    2 => ZMIDI_CLIP_ERROR_TRUNCATED,
    3 => ZMIDI_CLIP_ERROR_DATA_AFTER_END,
    4 => ZMIDI_CLIP_ERROR_BUFFER_TOO_SMALL,
    5 => ZMIDI_CLIP_ERROR_INVALID_CONFIG,
    6 => ZMIDI_CLIP_ERROR_INVALID_MESSAGE,
    7 => ZMIDI_CLIP_ERROR_OUT_OF_ORDER,
    8 => ZMIDI_CLIP_ERROR_PROPERTY_EXCHANGE,
    9 => ZMIDI_CLIP_ERROR_RESERVED_MESSAGE,
    10 => ZMIDI_CLIP_ERROR_TEMPO_TIMING,
    11 => ZMIDI_CLIP_ERROR_BAR_TIMING,
    12 => ZMIDI_CLIP_ERROR_FLEX_TIMING,
    13 => ZMIDI_CLIP_ERROR_WRONG_PHASE,
    _ => throw ArgumentError('Unknown value for ZmidiClipError: $value'),
  };
}

