/// Storage of one Property Exchange engine. The program gives it; [`zmidi_pe_init`] sets it up.
/// The program does not move or copy it after init. 16-byte alignment: the engine holds a `u128`.
final class ZmidiPe extends ffi.Struct {
  /// Opaque content.
  @ffi.Array.multi([488])
  external ffi.Array<ffi.Uint64> _opaque;
}

/// The end of a received Chunk (M2-103 5.3).
enum ZmidiPeChunkEnd {
  /// More Chunks follow.
  ZMIDI_PE_CHUNK_END_MORE(0),

  /// The last Chunk: the Property Data is complete.
  ZMIDI_PE_CHUNK_END_COMPLETE(1),

  /// The last Chunk: the Property Data is not known to be usable (REQ-PE-STAT-008).
  ZMIDI_PE_CHUNK_END_INCOMPLETE(2);

  final int value;
  const ZmidiPeChunkEnd(this.value);

  static ZmidiPeChunkEnd fromValue(int value) => switch (value) {
    0 => ZMIDI_PE_CHUNK_END_MORE,
    1 => ZMIDI_PE_CHUNK_END_COMPLETE,
    2 => ZMIDI_PE_CHUNK_END_INCOMPLETE,
    _ => throw ArgumentError('Unknown value for ZmidiPeChunkEnd: $value'),
  };
}

/// Why a transaction closed.
enum ZmidiPeCloseReason {
  /// The event is not a close.
  ZMIDI_PE_CLOSE_REASON_NONE(0),

  /// A deadline of this Device passed.
  ZMIDI_PE_CLOSE_REASON_TIMEOUT(1),

  /// The peer ended it: NAK 0x20 or Notify 144.
  ZMIDI_PE_CLOSE_REASON_TERMINATED(2),

  /// The peer timed out: NAK 0x42 or Notify 408.
  ZMIDI_PE_CLOSE_REASON_PEER_TIMEOUT(3),

  /// A Chunk came out of sequence; this Device sent NAK 0x21.
  ZMIDI_PE_CLOSE_REASON_OUT_OF_SEQUENCE(4),

  /// The peer sent another NAK: `nak_code` and `nak_data`.
  ZMIDI_PE_CLOSE_REASON_NAK(5),

  /// The Header Data of the reply is not valid.
  ZMIDI_PE_CLOSE_REASON_BAD_REPLY(6),

  /// This Device replied with the status `status` after an error.
  ZMIDI_PE_CLOSE_REASON_REFUSED(7),

  /// An Invalidate MUID ended it.
  ZMIDI_PE_CLOSE_REASON_INVALIDATED(8),

  /// A Flow Control resend that this Device can not do.
  ZMIDI_PE_CLOSE_REASON_RESEND_FAILED(9);

  final int value;
  const ZmidiPeCloseReason(this.value);

  static ZmidiPeCloseReason fromValue(int value) => switch (value) {
    0 => ZMIDI_PE_CLOSE_REASON_NONE,
    1 => ZMIDI_PE_CLOSE_REASON_TIMEOUT,
    2 => ZMIDI_PE_CLOSE_REASON_TERMINATED,
    3 => ZMIDI_PE_CLOSE_REASON_PEER_TIMEOUT,
    4 => ZMIDI_PE_CLOSE_REASON_OUT_OF_SEQUENCE,
    5 => ZMIDI_PE_CLOSE_REASON_NAK,
    6 => ZMIDI_PE_CLOSE_REASON_BAD_REPLY,
    7 => ZMIDI_PE_CLOSE_REASON_REFUSED,
    8 => ZMIDI_PE_CLOSE_REASON_INVALIDATED,
    9 => ZMIDI_PE_CLOSE_REASON_RESEND_FAILED,
    _ => throw ArgumentError('Unknown value for ZmidiPeCloseReason: $value'),
  };
}

/// The "command" of a Subscription message (M2-103 11).
enum ZmidiPeCommand {
  /// No "command".
  ZMIDI_PE_COMMAND_NONE(0),

  /// "start".
  ZMIDI_PE_COMMAND_START(1),

  /// "partial".
  ZMIDI_PE_COMMAND_PARTIAL(2),

  /// "full".
  ZMIDI_PE_COMMAND_FULL(3),

  /// "notify".
  ZMIDI_PE_COMMAND_NOTIFY(4),

  /// "end".
  ZMIDI_PE_COMMAND_END(5);

  final int value;
  const ZmidiPeCommand(this.value);

  static ZmidiPeCommand fromValue(int value) => switch (value) {
    0 => ZMIDI_PE_COMMAND_NONE,
    1 => ZMIDI_PE_COMMAND_START,
    2 => ZMIDI_PE_COMMAND_PARTIAL,
    3 => ZMIDI_PE_COMMAND_FULL,
    4 => ZMIDI_PE_COMMAND_NOTIFY,
    5 => ZMIDI_PE_COMMAND_END,
    _ => throw ArgumentError('Unknown value for ZmidiPeCommand: $value'),
  };
}

/// The encoding of Property Data (M2-103 Table 12).
enum ZmidiPeEncoding {
  /// "ASCII".
  ZMIDI_PE_ENCODING_ASCII(0),

  /// "Mcoded7".
  ZMIDI_PE_ENCODING_MCODED7(1),

  /// "zlib+Mcoded7": the event gives the zlib stream.
  ZMIDI_PE_ENCODING_ZLIB_MCODED7(2);

  final int value;
  const ZmidiPeEncoding(this.value);

  static ZmidiPeEncoding fromValue(int value) => switch (value) {
    0 => ZMIDI_PE_ENCODING_ASCII,
    1 => ZMIDI_PE_ENCODING_MCODED7,
    2 => ZMIDI_PE_ENCODING_ZLIB_MCODED7,
    _ => throw ArgumentError('Unknown value for ZmidiPeEncoding: $value'),
  };
}

/// The reason of the last refusal of the engine (REQ-FFI-PE-008): one value for each
/// `TransactionError` of zmidi-ci-pe, and the refusals of the C ABI.
enum ZmidiPeError {
  /// No refusal.
  ZMIDI_PE_ERROR_NONE(0),

  /// The zmidi-ci Device refused (unknown peer, no PE Capabilities, no free Request ID, a call
  /// that the build does not support).
  ZMIDI_PE_ERROR_DEVICE(1),

  /// A message writer failed: the output buffer is too small.
  ZMIDI_PE_ERROR_WRITE(2),

  /// The header writer refused the header.
  ZMIDI_PE_ERROR_HEADER(3),

  /// A subscription rule refused the message.
  ZMIDI_PE_ERROR_SUBSCRIPTION(4),

  /// No open transaction has this peer, Request ID and role, or no subscription this index.
  ZMIDI_PE_ERROR_UNKNOWN_TRANSACTION(5),

  /// All transaction slots are in use.
  ZMIDI_PE_ERROR_FULL(6),

  /// The peer has its maximum of open requests.
  ZMIDI_PE_ERROR_PEER_BUSY(7),

  /// The deadline passed; the transaction is closed.
  ZMIDI_PE_ERROR_LATE(8),

  /// The call does not fit the state of the transaction.
  ZMIDI_PE_ERROR_STATE(9),

  /// The ResourceList of the peer does not permit the request; the status it would get is
  /// given by [`zmidi_pe_last_error`].
  ZMIDI_PE_ERROR_REFUSED(10),

  /// Property Data that is not JSON needs a "mediaType".
  ZMIDI_PE_ERROR_NO_MEDIA_TYPE(11),

  /// A reply for a Resource with "canPaginate" needs "totalCount".
  ZMIDI_PE_ERROR_NO_TOTAL_COUNT(12),

  /// The header does not fit the header buffer or the first Chunk.
  ZMIDI_PE_ERROR_HEADER_TOO_LARGE(13),

  /// A Chunk part larger than the room of the Chunk, or a scratch buffer smaller than the
  /// received Property Data.
  ZMIDI_PE_ERROR_SIZE(14),

  /// The queue of control messages is full: call [`zmidi_pe_write_pending`] first.
  ZMIDI_PE_ERROR_QUEUE_FULL(15),

  /// A wait of 0 or more than 12.7 seconds.
  ZMIDI_PE_ERROR_INVALID_WAIT(16),

  /// A "$ref" value that is not "midi+jsonschema://<id>".
  ZMIDI_PE_ERROR_INVALID_REF(17);

  final int value;
  const ZmidiPeError(this.value);

  static ZmidiPeError fromValue(int value) => switch (value) {
    0 => ZMIDI_PE_ERROR_NONE,
    1 => ZMIDI_PE_ERROR_DEVICE,
    2 => ZMIDI_PE_ERROR_WRITE,
    3 => ZMIDI_PE_ERROR_HEADER,
    4 => ZMIDI_PE_ERROR_SUBSCRIPTION,
    5 => ZMIDI_PE_ERROR_UNKNOWN_TRANSACTION,
    6 => ZMIDI_PE_ERROR_FULL,
    7 => ZMIDI_PE_ERROR_PEER_BUSY,
    8 => ZMIDI_PE_ERROR_LATE,
    9 => ZMIDI_PE_ERROR_STATE,
    10 => ZMIDI_PE_ERROR_REFUSED,
    11 => ZMIDI_PE_ERROR_NO_MEDIA_TYPE,
    12 => ZMIDI_PE_ERROR_NO_TOTAL_COUNT,
    13 => ZMIDI_PE_ERROR_HEADER_TOO_LARGE,
    14 => ZMIDI_PE_ERROR_SIZE,
    15 => ZMIDI_PE_ERROR_QUEUE_FULL,
    16 => ZMIDI_PE_ERROR_INVALID_WAIT,
    17 => ZMIDI_PE_ERROR_INVALID_REF,
    _ => throw ArgumentError('Unknown value for ZmidiPeError: $value'),
  };
}

/// One event of the engine (REQ-FFI-PE-002, REQ-FFI-PE-010). The fields that the kind does not
/// use are 0, -1 or empty.
final class ZmidiPeEvent extends ffi.Struct {
  /// The kind; None when there is no event.
  @ffi.UnsignedInt()
  external int kindAsInt;

  ZmidiPeEventKind get kind => ZmidiPeEventKind.fromValue(kindAsInt);
  set kind(ZmidiPeEventKind value) => kindAsInt = value.value;

  /// The MUID of the peer (Invalidated: the invalidated MUID).
  @ffi.Uint32()
  external int muid;

  /// Request ID of the transaction.
  @ffi.Uint8()
  external int request_id;

  /// The role of this Device.
  @ffi.UnsignedInt()
  external int roleAsInt;

  ZmidiPeRole get role => ZmidiPeRole.fromValue(roleAsInt);
  set role(ZmidiPeRole value) => roleAsInt = value.value;

  /// The kind of the transaction.
  @ffi.UnsignedInt()
  external int txnAsInt;

  ZmidiPeTxnKind get txn => ZmidiPeTxnKind.fromValue(txnAsInt);
  set txn(ZmidiPeTxnKind value) => txnAsInt = value.value;

  /// Message: the end of this Chunk.
  @ffi.UnsignedInt()
  external int endAsInt;

  ZmidiPeChunkEnd get end => ZmidiPeChunkEnd.fromValue(endAsInt);
  set end(ZmidiPeChunkEnd value) => endAsInt = value.value;

  /// Message: the encoding of the Property Data.
  @ffi.UnsignedInt()
  external int encodingAsInt;

  ZmidiPeEncoding get encoding => ZmidiPeEncoding.fromValue(encodingAsInt);
  set encoding(ZmidiPeEncoding value) => encodingAsInt = value.value;

  /// Message: the "command" of the header.
  @ffi.UnsignedInt()
  external int commandAsInt;

  ZmidiPeCommand get command => ZmidiPeCommand.fromValue(commandAsInt);
  set command(ZmidiPeCommand value) => commandAsInt = value.value;

  /// Message: the "status" of the header, 0 when absent. Closed with Refused: the status.
  @ffi.Uint16()
  external int status;

  /// Resend: the number of the Chunk to send again.
  @ffi.Uint16()
  external int chunk;

  /// Message: the index of the Resource in the Resource table, or -1.
  @ffi.Int32()
  external int resource_index;

  /// Message: the subscription entry of the message, or -1. SubscriptionStarted: the new entry.
  @ffi.Int32()
  external int subscription;

  /// Message of the reply to a "start": the new subscription entry, or -1.
  @ffi.Int32()
  external int started;

  /// Message of the reply to a "start" with no new entry: why.
  @ffi.UnsignedInt()
  external int start_errorAsInt;

  ZmidiPeSubscriptionError get start_error =>
      ZmidiPeSubscriptionError.fromValue(start_errorAsInt);
  set start_error(ZmidiPeSubscriptionError value) =>
      start_errorAsInt = value.value;

  /// Closed: why.
  @ffi.UnsignedInt()
  external int reasonAsInt;

  ZmidiPeCloseReason get reason => ZmidiPeCloseReason.fromValue(reasonAsInt);
  set reason(ZmidiPeCloseReason value) => reasonAsInt = value.value;

  /// Closed with Nak: the NAK Status Code.
  @ffi.Uint8()
  external int nak_code;

  /// Closed with Nak: the NAK Status Data.
  @ffi.Uint8()
  external int nak_data;

  /// Invalidated: the number of removed subscriptions.
  @ffi.Uint32()
  external int ended;

  /// Message: the Header Data (first Chunk only), in the message of the program.
  external ffi.Pointer<ffi.Uint8> header;

  /// Bytes of `header`.
  @ffi.UintPtr()
  external int header_len;

  /// Message: the decoded Property Data of this Chunk, in the scratch buffer of the program.
  external ffi.Pointer<ffi.Uint8> data;

  /// Bytes of `data`.
  @ffi.UintPtr()
  external int data_len;

  /// Message: the decoded "resource" (NUL-terminated). SubscriptionEnded: the entry resource.
  @ffi.Array.multi([37])
  external ffi.Array<ffi.Uint8> resource;

  /// Message: the decoded "resId". SubscriptionEnded: the entry resId.
  @ffi.Array.multi([37])
  external ffi.Array<ffi.Uint8> res_id;

  /// Message: the decoded "subscribeId". SubscriptionEnded: the entry subscribeId.
  @ffi.Array.multi([37])
  external ffi.Array<ffi.Uint8> subscribe_id;
}

/// The kind of a [`ZmidiPeEvent`] (one for each `PeEvent` of zmidi-ci-pe).
enum ZmidiPeEventKind {
  /// No event.
  ZMIDI_PE_EVENT_KIND_NONE(0),

  /// A received Chunk of a message.
  ZMIDI_PE_EVENT_KIND_MESSAGE(1),

  /// Flow Control: send the next Chunk (REQ-PE-FLOW-002).
  ZMIDI_PE_EVENT_KIND_READY(2),

  /// Flow Control: send the Chunk `chunk` again (REQ-PE-FLOW-012, -013).
  ZMIDI_PE_EVENT_KIND_RESEND(3),

  /// A transaction closed; `reason` tells why.
  ZMIDI_PE_EVENT_KIND_CLOSED(4),

  /// This Device accepted a "start" and replied 200; `subscription` is the new entry.
  ZMIDI_PE_EVENT_KIND_SUBSCRIPTION_STARTED(5),

  /// The peer ended a subscription with "end"; the entry fields are in the event.
  ZMIDI_PE_EVENT_KIND_SUBSCRIPTION_ENDED(6),

  /// An Invalidate MUID closed the transactions of `muid`; `ended` subscriptions wait in
  /// [`zmidi_pe_take_ended`].
  ZMIDI_PE_EVENT_KIND_INVALIDATED(7);

  final int value;
  const ZmidiPeEventKind(this.value);

  static ZmidiPeEventKind fromValue(int value) => switch (value) {
    0 => ZMIDI_PE_EVENT_KIND_NONE,
    1 => ZMIDI_PE_EVENT_KIND_MESSAGE,
    2 => ZMIDI_PE_EVENT_KIND_READY,
    3 => ZMIDI_PE_EVENT_KIND_RESEND,
    4 => ZMIDI_PE_EVENT_KIND_CLOSED,
    5 => ZMIDI_PE_EVENT_KIND_SUBSCRIPTION_STARTED,
    6 => ZMIDI_PE_EVENT_KIND_SUBSCRIPTION_ENDED,
    7 => ZMIDI_PE_EVENT_KIND_INVALIDATED,
    _ => throw ArgumentError('Unknown value for ZmidiPeEventKind: $value'),
  };
}

/// The request Properties that the program gives to [`zmidi_pe_request`] and
/// [`zmidi_pe_subscribe`] (M2-103 8). The texts are NUL-terminated and stay valid during the call.
final class ZmidiPeHeader extends ffi.Struct {
  /// "resource".
  external ffi.Pointer<ffi.Uint8> resource;

  /// "resId", or null.
  external ffi.Pointer<ffi.Uint8> res_id;

  /// "mediaType" of the Property Data of a Set, or null for JSON.
  external ffi.Pointer<ffi.Uint8> media_type;

  /// True when the request has "offset" and "limit" (REQ-PE-TXN-006).
  @ffi.Bool()
  external bool has_offset;

  /// "offset".
  @ffi.Uint32()
  external int offset;

  /// "limit", 1 and up.
  @ffi.Uint32()
  external int limit;

  /// "setPartial".
  @ffi.Bool()
  external bool set_partial;

  /// The [`ZmidiPeEncoding`] of the Property Data that the program sends; for a Get, the
  /// encoding that it asks for the reply.
  @ffi.Uint8()
  external int encoding;

  /// Bytes of the encoded Property Data that the program sends (0 for a Get); `SIZE_MAX` when
  /// not known.
  @ffi.UintPtr()
  external int length;

  static ffi.Pointer<ZmidiPeHeader> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Uint8> resource,
    required ffi.Pointer<ffi.Uint8> res_id,
    required ffi.Pointer<ffi.Uint8> media_type,
    required bool has_offset,
    required int offset,
    required int limit,
    required bool set_partial,
    required int encoding,
    required int length,
  }) => $allocator<ZmidiPeHeader>()
    ..ref.resource = resource
    ..ref.res_id = res_id
    ..ref.media_type = media_type
    ..ref.has_offset = has_offset
    ..ref.offset = offset
    ..ref.limit = limit
    ..ref.set_partial = set_partial
    ..ref.encoding = encoding
    ..ref.length = length;
}

/// One entry of the Resource table (M2-103 Table 14, REQ-FFI-PE-009). The texts are
/// NUL-terminated and stay valid while the engine is used.
final class ZmidiPeResource extends ffi.Struct {
  /// "resource": 1 to 36 characters A-Z, a-z, 0-9 with an optional "X-" prefix.
  external ffi.Pointer<ffi.Uint8> resource;

  /// "canGet".
  @ffi.Bool()
  external bool can_get;

  /// "canSet": 0 "none", 1 "full", 2 "partial".
  @ffi.Uint8()
  external int can_set;

  /// "canSubscribe".
  @ffi.Bool()
  external bool can_subscribe;

  /// "requireResId".
  @ffi.Bool()
  external bool require_res_id;

  /// "fcOnGet".
  @ffi.Bool()
  external bool fc_on_get;

  /// "fcOnSet".
  @ffi.Bool()
  external bool fc_on_set;

  /// "canPaginate".
  @ffi.Bool()
  external bool can_paginate;

  /// Write every Property, also the ones with their default value (REQ-PE-LIST-009).
  @ffi.Bool()
  external bool write_defaults;

  /// "encodings": bit n is the [`ZmidiPeEncoding`] of value n; at least one bit.
  @ffi.Uint8()
  external int encodings;

  /// The one "mediaType" ("type/subtype", at most 75 characters), or null for
  /// "application/json".
  external ffi.Pointer<ffi.Uint8> media_type;

  /// "schema" as JSON text, or null.
  external ffi.Pointer<ffi.Uint8> schema;

  /// Bytes of `schema`.
  @ffi.UintPtr()
  external int schema_len;

  static ffi.Pointer<ZmidiPeResource> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Uint8> resource,
    required bool can_get,
    required int can_set,
    required bool can_subscribe,
    required bool require_res_id,
    required bool fc_on_get,
    required bool fc_on_set,
    required bool can_paginate,
    required bool write_defaults,
    required int encodings,
    required ffi.Pointer<ffi.Uint8> media_type,
    required ffi.Pointer<ffi.Uint8> schema,
    required int schema_len,
  }) => $allocator<ZmidiPeResource>()
    ..ref.resource = resource
    ..ref.can_get = can_get
    ..ref.can_set = can_set
    ..ref.can_subscribe = can_subscribe
    ..ref.require_res_id = require_res_id
    ..ref.fc_on_get = fc_on_get
    ..ref.fc_on_set = fc_on_set
    ..ref.can_paginate = can_paginate
    ..ref.write_defaults = write_defaults
    ..ref.encodings = encodings
    ..ref.media_type = media_type
    ..ref.schema = schema
    ..ref.schema_len = schema_len;
}

/// The role of this Device in a transaction or a subscription.
enum ZmidiPeRole {
  /// This Device sent the inquiry or the "start".
  ZMIDI_PE_ROLE_INITIATOR(0),

  /// This Device answers.
  ZMIDI_PE_ROLE_RESPONDER(1);

  final int value;
  const ZmidiPeRole(this.value);

  static ZmidiPeRole fromValue(int value) => switch (value) {
    0 => ZMIDI_PE_ROLE_INITIATOR,
    1 => ZMIDI_PE_ROLE_RESPONDER,
    _ => throw ArgumentError('Unknown value for ZmidiPeRole: $value'),
  };
}

/// A copy of one subscription table entry (REQ-FFI-PE-007).
final class ZmidiPeSubscription extends ffi.Struct {
  /// The MUID of the peer.
  @ffi.Uint32()
  external int muid;

  /// The role of this Device.
  @ffi.UnsignedInt()
  external int roleAsInt;

  ZmidiPeRole get role => ZmidiPeRole.fromValue(roleAsInt);
  set role(ZmidiPeRole value) => roleAsInt = value.value;

  /// "subscribeId" (NUL-terminated).
  @ffi.Array.multi([37])
  external ffi.Array<ffi.Uint8> subscribe_id;

  /// "resource" (NUL-terminated).
  @ffi.Array.multi([37])
  external ffi.Array<ffi.Uint8> resource;

  /// "resId" (NUL-terminated, empty when absent).
  @ffi.Array.multi([37])
  external ffi.Array<ffi.Uint8> res_id;
}

/// Why the reply to a "start" gave no subscription (REQ-PE-SUB-006).
enum ZmidiPeSubscriptionError {
  /// No error.
  ZMIDI_PE_SUBSCRIPTION_ERROR_NONE(0),

  /// The subscription table is full.
  ZMIDI_PE_SUBSCRIPTION_ERROR_FULL(1),

  /// The reply has no "subscribeId".
  ZMIDI_PE_SUBSCRIPTION_ERROR_NO_SUBSCRIBE_ID(2),

  /// The reply has no status from 200 to 299.
  ZMIDI_PE_SUBSCRIPTION_ERROR_NOT_SUCCESS(3),

  /// A command or Property Data that the role does not permit.
  ZMIDI_PE_SUBSCRIPTION_ERROR_NOT_PERMITTED(4),

  /// A header value is longer than the entry buffers, or a Property is missing.
  ZMIDI_PE_SUBSCRIPTION_ERROR_INVALID(5);

  final int value;
  const ZmidiPeSubscriptionError(this.value);

  static ZmidiPeSubscriptionError fromValue(int value) => switch (value) {
    0 => ZMIDI_PE_SUBSCRIPTION_ERROR_NONE,
    1 => ZMIDI_PE_SUBSCRIPTION_ERROR_FULL,
    2 => ZMIDI_PE_SUBSCRIPTION_ERROR_NO_SUBSCRIBE_ID,
    3 => ZMIDI_PE_SUBSCRIPTION_ERROR_NOT_SUCCESS,
    4 => ZMIDI_PE_SUBSCRIPTION_ERROR_NOT_PERMITTED,
    5 => ZMIDI_PE_SUBSCRIPTION_ERROR_INVALID,
    _ => throw ArgumentError(
      'Unknown value for ZmidiPeSubscriptionError: $value',
    ),
  };
}

/// The kind of a transaction.
enum ZmidiPeTxnKind {
  /// Get Property Data and its reply.
  ZMIDI_PE_TXN_KIND_GET(0),

  /// Set Property Data and its reply.
  ZMIDI_PE_TXN_KIND_SET(1),

  /// Subscription and its reply.
  ZMIDI_PE_TXN_KIND_SUBSCRIPTION(2);

  final int value;
  const ZmidiPeTxnKind(this.value);

  static ZmidiPeTxnKind fromValue(int value) => switch (value) {
    0 => ZMIDI_PE_TXN_KIND_GET,
    1 => ZMIDI_PE_TXN_KIND_SET,
    2 => ZMIDI_PE_TXN_KIND_SUBSCRIPTION,
    _ => throw ArgumentError('Unknown value for ZmidiPeTxnKind: $value'),
  };
}

/// The result of a function of the C ABI. New values go at the end only; a value never changes.
enum ZmidiStatus {
  /// The function did its work.
  ZMIDI_STATUS_OK(0),

  /// A pointer is null, or a value is out of its range. No state changed.
  ZMIDI_STATUS_INVALID_ARGUMENT(1),

  /// The output buffer of the program is too small. No state changed.
  ZMIDI_STATUS_BUFFER_TOO_SMALL(2),

  /// A reply call has no pending event to answer, or an event call has no event of its kind.
  ZMIDI_STATUS_NO_PENDING(3),

  /// The library refused the request (for example a request to an unknown peer).
  ZMIDI_STATUS_REJECTED(4),

  /// This build has no support for the request.
  ZMIDI_STATUS_NOT_SUPPORTED(5);

  final int value;
  const ZmidiStatus(this.value);

  static ZmidiStatus fromValue(int value) => switch (value) {
    0 => ZMIDI_STATUS_OK,
    1 => ZMIDI_STATUS_INVALID_ARGUMENT,
    2 => ZMIDI_STATUS_BUFFER_TOO_SMALL,
    3 => ZMIDI_STATUS_NO_PENDING,
    4 => ZMIDI_STATUS_REJECTED,
    5 => ZMIDI_STATUS_NOT_SUPPORTED,
    _ => throw ArgumentError('Unknown value for ZmidiStatus: $value'),
  };
}

/// One UMP as plain values (REQ-FFI-UMP-002).
final class ZmidiUmpInfo extends ffi.Struct {
  /// Message Type, 0x0 to 0xF.
  @ffi.Uint8()
  external int message_type;

  /// Words of the UMP, 1 to 4 (M2-104 Table 4).
  @ffi.Uint8()
  external int word_count;

  /// True when the Message Type has a Group field.
  @ffi.Bool()
  external bool has_group;

  /// Group, 0 to 15, when `has_group`.
  @ffi.Uint8()
  external int group;

  /// True when the Message Type has a status field.
  @ffi.Bool()
  external bool has_status;

  /// Status: the opcode or status nibble (Message Types 0x0, 0x2 to 0x5) or the status byte
  /// (Message Type 0x1), when `has_status`.
  @ffi.Uint8()
  external int status;

  /// True when the Message Type has a Channel field.
  @ffi.Bool()
  external bool has_channel;

  /// Channel, 0 to 15, when `has_channel`.
  @ffi.Uint8()
  external int channel;

  /// True when this build decodes the Message Type (zmidi-ump features, DEC-017).
  @ffi.Bool()
  external bool decoded;

  /// The words of the UMP; words after `word_count` are 0.
  @ffi.Array.multi([4])
  external ffi.Array<ffi.Uint32> words;
}

/// Storage of one byte stream writer. The program gives it; [`zmidi_ump_to_bytes_init`] sets it up.
final class ZmidiUmpToBytes extends ffi.Struct {
  /// Opaque content.
  @ffi.Array.multi([1])
  external ffi.Array<ffi.Uint64> _opaque;
}

/// One Group Terminal Block (USB-MIDI v2.0 Table 5-6). The fields are the raw descriptor values.
final class ZmidiUsbBlock extends ffi.Struct {
  /// bGrpTrmBlkID, 1 to 255.
  @ffi.Uint8()
  external int id;

  /// bGrpTrmBlkType: 0 bidirectional, 1 input only, 2 output only.
  @ffi.Uint8()
  external int kind;

  /// nGroupTrm: the first member Group Terminal Number, 0x0 to 0xF.
  @ffi.Uint8()
  external int first_group;

  /// nNumGroupTrm: the number of member Group Terminals, 1 to 16 - `first_group`.
  @ffi.Uint8()
  external int num_groups;

  /// iBlockItem; 0 is no string.
  @ffi.Uint8()
  external int string_index;

  /// bMIDIProtocol (for example 0x11 MIDI 2.0, 0x03 MIDI 1.0 with UMPs up to 128 bits).
  @ffi.Uint8()
  external int protocol;

  /// wMaxInputBandwidth: 0 unknown, else units of 4000 bytes per second.
  @ffi.Uint16()
  external int max_input_bandwidth;

  /// wMaxOutputBandwidth: 0 unknown, else units of 4000 bytes per second.
  @ffi.Uint16()
  external int max_output_bandwidth;

  static ffi.Pointer<ZmidiUsbBlock> $allocate(
    ffi.Allocator $allocator, {
    required int id,
    required int kind,
    required int first_group,
